package com.example.platform.studio.shotscene;
import com.example.platform.shared.digest.ContentDigest;import com.example.platform.studio.digest.StudioDigest;import com.example.platform.studio.identity.*;import com.example.platform.studio.reference.StudioVersionPin;import com.example.platform.studio.scene.SceneVersion;import com.example.platform.studio.scope.StudioScope;import com.example.platform.studio.screenplay.ScreenplayVersion;import com.example.platform.studio.serialization.CanonicalJson;import com.example.platform.studio.shotplan.ShotPlanVersion;import java.util.*;
public final class ShotSceneVersion implements com.example.platform.studio.digest.CanonicalStudioVersion{public static final int SCHEMA_VERSION=1;private final ShotSceneId id;private final ShotSceneVersionId versionId;private final StudioScope scope;private final ShotSceneVersionId parentVersionId;private final StudioVersionPin<ShotPlanId,ShotPlanVersionId>shotPlanPin;private final StudioVersionPin<ScreenplayId,ScreenplayVersionId>screenplayPin;private final StudioVersionPin<SceneId,SceneVersionId>scenePin;private final List<SceneElement>elements;private final byte[]canonicalBytes;private final ContentDigest semanticDigest;
private ShotSceneVersion(ShotSceneId id,ShotSceneVersionId versionId,StudioScope scope,ShotSceneVersionId parentVersionId,ShotPlanVersion plan,ScreenplayVersion screenplay,SceneVersion scene,List<SceneElement>elements){if(id==null||versionId==null||scope==null||plan==null||screenplay==null||scene==null||elements==null)throw new IllegalArgumentException("shot scene fields required");if(versionId.equals(parentVersionId))throw new IllegalArgumentException("version cannot parent itself");if(!scope.equals(plan.scope())||!scope.equals(screenplay.scope())||!scope.equals(scene.scope()))throw new IllegalArgumentException("scope mismatch");if(!plan.screenplayPin().equals(screenplay.pin())||!plan.scenePin().equals(scene.pin()))throw new IllegalArgumentException("shot scene lineage mismatch");validateForest(elements);this.id=id;this.versionId=versionId;this.scope=scope;this.parentVersionId=parentVersionId;this.shotPlanPin=plan.pin();this.screenplayPin=screenplay.pin();this.scenePin=scene.pin();this.elements=List.copyOf(elements);this.canonicalBytes=serialize();this.semanticDigest=StudioDigest.sha256(canonicalBytes);}
public static ShotSceneVersion create(ShotSceneId id,ShotSceneVersionId versionId,StudioScope scope,ShotSceneVersionId parentVersionId,ShotPlanVersion plan,ScreenplayVersion screenplay,SceneVersion scene,List<SceneElement>elements){if(elements!=null)for(var element:elements)if(element!=null&&element.cameraPlanPin()!=null&&!element.cameraPlanPin().scope().equals(scope))throw new IllegalArgumentException("camera plan scope mismatch");return new ShotSceneVersion(id,versionId,scope,parentVersionId,plan,screenplay,scene,elements);}
private static void validateForest(List<SceneElement>elements){var byId=new LinkedHashMap<SceneElementId,SceneElement>();for(var e:elements)if(e==null||byId.putIfAbsent(e.id(),e)!=null)throw new IllegalArgumentException("duplicate scene element identity");for(var e:elements){if(e.parentId()!=null&&!byId.containsKey(e.parentId()))throw new IllegalArgumentException("dangling parent reference");for(var r:e.references())if(!byId.containsKey(r))throw new IllegalArgumentException("dangling local reference");}var visiting=new HashSet<SceneElementId>();var visited=new HashSet<SceneElementId>();for(var e:elements)visit(e.id(),byId,visiting,visited);}
private static void visit(SceneElementId id,Map<SceneElementId,SceneElement>byId,Set<SceneElementId>visiting,Set<SceneElementId>visited){if(visited.contains(id))return;if(!visiting.add(id))throw new IllegalArgumentException("scene element hierarchy cycle");var parent=byId.get(id).parentId();if(parent!=null)visit(parent,byId,visiting,visited);visiting.remove(id);visited.add(id);}
private byte[]serialize(){Map<String,String>m=new LinkedHashMap<>();m.put("aggregateId",CanonicalJson.quote(id.value()));m.put("elements",CanonicalJson.array(elements.stream().map(SceneElement::canonicalJson).toList()));if(parentVersionId!=null)m.put("parentVersionId",CanonicalJson.quote(parentVersionId.value()));m.put("projectId",CanonicalJson.quote(scope.projectId().value()));m.put("scenePin",scenePin.canonicalJson());m.put("schemaVersion","1");m.put("screenplayPin",screenplayPin.canonicalJson());m.put("shotPlanPin",shotPlanPin.canonicalJson());m.put("spatialConvention",CanonicalJson.quote("RIGHT_HANDED_X_RIGHT_Y_UP_CAMERA_FORWARD_NEGATIVE_Z_METERS_DEGREES"));m.put("tenantId",CanonicalJson.quote(scope.tenantId().value()));m.put("type",CanonicalJson.quote("SHOT_SCENE_VERSION"));m.put("versionId",CanonicalJson.quote(versionId.value()));return CanonicalJson.utf8(CanonicalJson.object(m));}
public StudioVersionPin<ShotSceneId,ShotSceneVersionId>pin(){return new StudioVersionPin<>(StudioVersionPin.AggregateKind.SHOT_SCENE,id,versionId,scope,1,semanticDigest);}public ShotSceneId id(){return id;}public ShotSceneVersionId versionId(){return versionId;}public StudioScope scope(){return scope;}public ShotSceneVersionId parentVersionId(){return parentVersionId;}public StudioVersionPin<ShotPlanId,ShotPlanVersionId>shotPlanPin(){return shotPlanPin;}public List<SceneElement>elements(){return elements;}public byte[]canonicalBytes(){return canonicalBytes.clone();}public ContentDigest semanticDigest(){return semanticDigest;}}
